using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n + 1);                       // a[i] = 1 表示 i 号房间被占用
    for (int i = 1; i <= n; i++) cin >> a[i];
    int k;
    cin >> k;                                   // 客人想住的房间编号

    // 情况一：想要的房间空着，直接安排进去。
    if (a[k] == 0) {
        cout << k << "\n";
        return 0;
    }

